    37	/* This is the callout function. Its only purpose is to halt matching if there 
    38	are more than 100 callouts, as one way of stopping too much time being spent on 
    39	fruitless matches. The callout data is a pointer to the counter. */
    40	
    41	static int callout_function(pcre2_callout_block *cb, void *callout_data)
    42	{
    43	(void)cb;  /* Avoid unused parameter warning */
    44	*((uint32_t *)callout_data) += 1;
    45	return (*((uint32_t *)callout_data) > 100)? PCRE2_ERROR_CALLOUT : 0;
    46	}
