    52	
    53	/* Here's the driving function. */
    54	
    55	int LLVMFuzzerTestOneInput(const unsigned char *data, size_t size)
    56	{
    57	uint32_t compile_options;
    58	uint32_t match_options;
    59	pcre2_match_data *match_data = NULL;
    60	pcre2_match_context *match_context = NULL;
    61	size_t match_size;
    62	int r1, r2;
    63	int i;
    64	
    65	if (size < 1) return 0;
    66	
    67	/* Limiting the length of the subject for matching stops fruitless searches 
    68	in large trees taking too much time. */
    69	
    70	match_size = (size > MAX_MATCH_SIZE)? MAX_MATCH_SIZE : size;
    71	
    72	/* Figure out some options to use. Initialize the random number to ensure
    73	repeatability. Ensure that we get a 32-bit unsigned random number for testing
    74	options. (RAND_MAX is required to be at least 32767, but is commonly
    75	2147483647, which excludes the top bit.) */
    76	
    77	srand((unsigned int)(data[size/2]));
    78	r1 = rand();
    79	r2 = rand();
    80	
    81	/* Ensure that all undefined option bits are zero (waste of time trying them)
    82	and also that PCRE2_NO_UTF_CHECK is unset, as there is no guarantee that the
    83	input is UTF-8. Also unset PCRE2_NEVER_UTF and PCRE2_NEVER_UCP as there is no
    84	reason to disallow UTF and UCP. Force PCRE2_NEVER_BACKSLASH_C to be set because
    85	\C in random patterns is highly likely to cause a crash.  */
    86	
    87	compile_options =
    88	  ((((uint32_t)r1 << 16) | ((uint32_t)r2 & 0xffff)) & ALLOWED_COMPILE_OPTIONS) |
    89	  PCRE2_NEVER_BACKSLASH_C;
    90	
    91	match_options =
    92	  ((((uint32_t)r1 << 16) | ((uint32_t)r2 & 0xffff)) & ALLOWED_MATCH_OPTIONS);
    93	
    94	/* Do the compile with and without the options, and after a successful compile,
    95	likewise do the match with and without the options. */
    96	
    97	for (i = 0; i < 2; i++)
    98	  {
    99	  uint32_t callout_count;
   100	  int errorcode;
   101	  PCRE2_SIZE erroroffset;
   102	  pcre2_code *code;
   103	
   104	#ifdef STANDALONE
   105	  printf("Compile options %.8x never_backslash_c", compile_options);
   106	  printf("%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s\n",
   107	    ((compile_options & PCRE2_ALT_BSUX) != 0)? ",alt_bsux" : "",
   108	    ((compile_options & PCRE2_ALT_CIRCUMFLEX) != 0)? ",alt_circumflex" : "",
   109	    ((compile_options & PCRE2_ALT_VERBNAMES) != 0)? ",alt_verbnames" : "",
   110	    ((compile_options & PCRE2_ALLOW_EMPTY_CLASS) != 0)? ",allow_empty_class" : "",
   111	    ((compile_options & PCRE2_ANCHORED) != 0)? ",anchored" : "",
   112	    ((compile_options & PCRE2_AUTO_CALLOUT) != 0)? ",auto_callout" : "",
   113	    ((compile_options & PCRE2_CASELESS) != 0)? ",caseless" : "",
   114	    ((compile_options & PCRE2_DOLLAR_ENDONLY) != 0)? ",dollar_endonly" : "",
   115	    ((compile_options & PCRE2_DOTALL) != 0)? ",dotall" : "",
   116	    ((compile_options & PCRE2_DUPNAMES) != 0)? ",dupnames" : "",
   117	    ((compile_options & PCRE2_ENDANCHORED) != 0)? ",endanchored" : "",
   118	    ((compile_options & PCRE2_EXTENDED) != 0)? ",extended" : "",
   119	    ((compile_options & PCRE2_FIRSTLINE) != 0)? ",firstline" : "",
   120	    ((compile_options & PCRE2_MATCH_UNSET_BACKREF) != 0)? ",match_unset_backref" : "",
   121	    ((compile_options & PCRE2_MULTILINE) != 0)? ",multiline" : "",
   122	    ((compile_options & PCRE2_NEVER_UCP) != 0)? ",never_ucp" : "",
   123	    ((compile_options & PCRE2_NEVER_UTF) != 0)? ",never_utf" : "",
   124	    ((compile_options & PCRE2_NO_AUTO_CAPTURE) != 0)? ",no_auto_capture" : "",
   125	    ((compile_options & PCRE2_NO_AUTO_POSSESS) != 0)? ",no_auto_possess" : "",
   126	    ((compile_options & PCRE2_NO_DOTSTAR_ANCHOR) != 0)? ",no_dotstar_anchor" : "",
   127	    ((compile_options & PCRE2_NO_UTF_CHECK) != 0)? ",no_utf_check" : "",
   128	    ((compile_options & PCRE2_NO_START_OPTIMIZE) != 0)? ",no_start_optimize" : "",
   129	    ((compile_options & PCRE2_UCP) != 0)? ",ucp" : "",
   130	    ((compile_options & PCRE2_UNGREEDY) != 0)? ",ungreedy" : "",
   131	    ((compile_options & PCRE2_USE_OFFSET_LIMIT) != 0)? ",use_offset_limit" : "",
   132	    ((compile_options & PCRE2_UTF) != 0)? ",utf" : "");
   133	#endif
   134	
   135	  code = pcre2_compile((PCRE2_SPTR)data, (PCRE2_SIZE)size, compile_options,
   136	    &errorcode, &erroroffset, NULL);
   137	    
   138	  /* Compilation succeeded */
   139	
   140	  if (code != NULL)
   141	    {
   142	    int j;
   143	    uint32_t save_match_options = match_options;
   144	
   145	    /* Create match data and context blocks only when we first need them. Set
   146	    low match and depth limits to avoid wasting too much searching large
   147	    pattern trees. Almost all matches are going to fail. */
   148	
   149	    if (match_data == NULL)
   150	      {
   151	      match_data = pcre2_match_data_create(32, NULL);
   152	      if (match_data == NULL)
   153	        {
   154	#ifdef STANDALONE
   155	        printf("** Failed to create match data block\n");
   156	#endif
   157	        return 0;
   158	        }
   159	      }
   160	
   161	    if (match_context == NULL)
   162	      {
   163	      match_context = pcre2_match_context_create(NULL);
   164	      if (match_context == NULL)
   165	        {
   166	#ifdef STANDALONE
   167	        printf("** Failed to create match context block\n");
   168	#endif
   169	        return 0;
   170	        }
   171	      (void)pcre2_set_match_limit(match_context, 100);
   172	      (void)pcre2_set_depth_limit(match_context, 100); 
   173	      (void)pcre2_set_callout(match_context, callout_function, &callout_count); 
   174	      }
   175	
   176	    /* Match twice, with and without options */
   177	
   178	    for (j = 0; j < 2; j++)
   179	      {
   180	#ifdef STANDALONE
   181	      printf("Match options %.8x", match_options);
   182	      printf("%s%s%s%s%s%s%s%s%s\n",
   183	        ((match_options & PCRE2_ANCHORED) != 0)? ",anchored" : "",
   184	        ((match_options & PCRE2_ENDANCHORED) != 0)? ",endanchored" : "",
   185	        ((match_options & PCRE2_NO_UTF_CHECK) != 0)? ",no_utf_check" : "",
   186	        ((match_options & PCRE2_NOTBOL) != 0)? ",notbol" : "",
   187	        ((match_options & PCRE2_NOTEMPTY) != 0)? ",notempty" : "",
   188	        ((match_options & PCRE2_NOTEMPTY_ATSTART) != 0)? ",notempty_atstart" : "",
   189	        ((match_options & PCRE2_NOTEOL) != 0)? ",noteol" : "",
   190	        ((match_options & PCRE2_PARTIAL_HARD) != 0)? ",partial_hard" : "",
   191	        ((match_options & PCRE2_PARTIAL_SOFT) != 0)? ",partial_soft" : "");
   192	#endif
   193	
   194	      callout_count = 0;
   195	      errorcode = pcre2_match(code, (PCRE2_SPTR)data, (PCRE2_SIZE)match_size, 0,
   196	        match_options, match_data, match_context);
   197	
   198	#ifdef STANDALONE
   199	      if (errorcode >= 0) printf("Match returned %d\n", errorcode); else
   200	        {
   201	        unsigned char buffer[256];
   202	        pcre2_get_error_message(errorcode, buffer, 256);
   203	        printf("Match failed: error %d: %s\n", errorcode, buffer);
   204	        }
   205	#endif
   206	
   207	      match_options = 0;  /* For second time */
   208	      }
   209	
   210	    match_options = save_match_options;  /* Reset for the second compile */
   211	    pcre2_code_free(code);
   212	    }
   213	    
   214	  /* Compilation failed */
   215	
   216	  else
   217	    {
   218	    unsigned char buffer[256];
   219	    pcre2_get_error_message(errorcode, buffer, 256);
   220	#ifdef STANDALONE
   221	    printf("Error %d at offset %lu: %s\n", errorcode, erroroffset, buffer);
   222	#else
   223	    if (strstr((const char *)buffer, "internal error") != NULL) abort();
   224	#endif
   225	    }
   226	
   227	  compile_options = PCRE2_NEVER_BACKSLASH_C;  /* For second time */
   228	  }
   229	
   230	if (match_data != NULL) pcre2_match_data_free(match_data);
   231	if (match_context != NULL) pcre2_match_context_free(match_context);
   232	
   233	return 0;
   234	}
