   272	      LLVMFuzzerTestOneInput(buffer, readsize);
   273	      free(buffer);    
   274	      } 
   275	    continue;
   276	    }  
   277	
   278	  /* Handle a string given in a file */
   279	 
   280	  f = fopen(argv[i], "rb");
   281	  if (f == NULL)
   282	    {
   283	    printf("** Failed to open %s: %s\n", argv[i], strerror(errno));
   284	    continue;
   285	    }
   286	
   287	  printf("------ %s ------\n", argv[i]);
   288	
   289	  fseek(f, 0, SEEK_END);
   290	  filelen = ftell(f);
   291	  fseek(f, 0, SEEK_SET);
   292	
   293	  buffer = (unsigned char *)malloc(filelen);
   294	  if (buffer == NULL)
   295	    {
   296	    printf("** Failed to allocate %lu bytes of memory\n", filelen);
   297	    fclose(f);
