   299	    }
   300	
   301	  readsize = fread(buffer, 1, filelen, f);
   302	  fclose(f);
   303	
   304	  if (readsize != filelen)
   305	    printf("** File size is %lu but fread() returned %lu\n", filelen, readsize);
   306	  else
   307	    {
   308	    printf("Length = %lu\n", filelen);
   309	    LLVMFuzzerTestOneInput(buffer, filelen);
   310	    }
